SET @prov_c := '%s';
SET @id:= '%s';
SET @cat_id := '%s';
SET @b_year:=(SELECT yearprocess FROM pk_byear LIMIT 1);
SET @send :=  IF((SELECT active FROM sys_report WHERE cat_id = @cat_id and id = @id )=1,0,2);
SET	@start_d:=concat(@b_year-1,'1001');
SET @end_d:=concat(@b_year,'0930');

CREATE TABLE IF NOT EXISTS s_smiv3(
  id varchar(32) NOT NULL,
  hospcode varchar(5) NOT NULL,
  areacode varchar(8) NOT NULL,
  flag_sent varchar(1) DEFAULT NULL,
  date_com varchar(14) DEFAULT NULL,
  b_year varchar(4) NOT NULL,
	target int(9) DEFAULT 0,
	result1 int(9) DEFAULT 0,
	result2 int(9) DEFAULT 0,
	target1 int(9) DEFAULT 0,
	target2 int(9) DEFAULT 0,
	PRIMARY KEY (id,hospcode,areacode,b_year),
	KEY (hospcode),
	KEY (areacode),
	KEY (b_year)
) ENGINE=MyISAM DEFAULT CHARSET=utf8;

DELETE FROM s_smiv3 WHERE id=@id AND b_year=(@b_year+543);
CALL AddCol('hdc','s_smiv3','target1','int(9) DEFAULT 0 ');
CALL AddCol('hdc','s_smiv3','target2','int(9) DEFAULT 0 ');


DROP	TABLE IF EXISTS tmp_smiv_fu;
CREATE	TABLE IF NOT EXISTS tmp_smiv_fu(
hospcode varchar(5),
cid  varchar(13),
g_code text,
f_diag date,
in_year decimal(1,0) DEFAULT 0,
fu_last date,
d365 DECIMAL(1,0) DEFAULT 0,
count_fu int(9),
PRIMARY KEY(hospcode,cid),
KEY(hospcode,cid),
KEY(cid)
) ENGINE=MyISAM DEFAULT CHARSET=utf8;

INSERT IGNORE INTO tmp_smiv_fu (hospcode,cid)
SELECT p.HOSPCODE,p.cid
FROM tmp_smiv_special t INNER JOIN t_person_db p ON t.HOSPCODE=p.HOSPCODE AND t.cid=p.cid
INNER JOIN chospital h on p.HOSPCODE=h.hoscode
WHERE h.provcode=@prov_c AND p.NATION IN(99) AND p.DISCHARGE IN(9) AND t.ppspecial NOT IN ('1B036');
/*first and group*/
UPDATE tmp_smiv_fu t INNER JOIN  (
SELECT cid
,SUBSTRING_INDEX(GROUP_CONCAT(DATE_SERV ORDER BY DATE_SERV ASC),',',1) f_diag
,GROUP_CONCAT(CONCAT('{"HOSPCODE":"',hospcode,'","DATE_SERV":"',date_serv
		,'","PPSPECIAL":"',ppspecial,'"}') ORDER BY date_serv ASC) as g_code
FROM tmp_smiv_special 
GROUP BY cid
) as g ON t.cid=g.cid 
SET t.f_diag=g.f_diag ,t.g_code=g.g_code;

/*in_year*/
UPDATE tmp_smiv_fu t INNER JOIN  tmp_smiv_special s ON t.hospcode=s.hospcode AND t.cid=s.cid
SET t.in_year=1 
WHERE s.date_serv BETWEEN @start_d and @end_d;

/*fu last*/
UPDATE tmp_smiv_fu t INNER JOIN  (
SELECT p.hospcode,p.cid
,SUBSTRING_INDEX(GROUP_CONCAT(t.DATE_SERV ORDER BY t.DATE_SERV DESC),',',1) fu_last
FROM tmp_smiv_special t INNER JOIN t_person_db p ON t.HOSPCODE=p.HOSPCODE AND t.cid=p.cid
INNER JOIN chospital h on p.HOSPCODE=h.hoscode
WHERE h.provcode=@prov_c AND t.PPSPECIAL IN('1B037')
AND t.date_serv BETWEEN @start_d AND @end_d
GROUP BY p.hospcode,p.cid
) as g ON t.hospcode=g.hospcode AND t.cid=g.cid 
SET t.fu_last=g.fu_last ;

UPDATE tmp_smiv_fu SET d365=1 WHERE TIMESTAMPDIFF(day,f_diag,fu_last)<=365;

/*fu last*/
UPDATE tmp_smiv_fu t INNER JOIN  (
SELECT p.hospcode,p.cid,count(*) as count_fu
FROM tmp_smiv_special t 
INNER JOIN t_person_db p ON t.HOSPCODE=p.HOSPCODE AND t.cid=p.cid
INNER JOIN tmp_smiv_fu f ON t.HOSPCODE=f.HOSPCODE AND t.cid=f.cid
INNER JOIN chospital h on p.HOSPCODE=h.hoscode
WHERE h.provcode=@prov_c AND t.PPSPECIAL IN('1B037')
AND t.date_serv BETWEEN DATE_SUB(f.fu_last,INTERVAL 365 day ) AND f.fu_last
GROUP BY p.hospcode,p.cid
) as g ON t.hospcode=g.hospcode AND t.cid=g.cid 
SET t.count_fu=g.count_fu ;

INSERT IGNORE INTO s_smiv3 (id,hospcode,areacode,flag_sent,date_com,b_year,target,target1,target2,result1,result2)

SELECT 
    @id,h.hoscode	,concat(h.provcode,SUBSTR(CONCAT('00',h.distcode),-2),SUBSTR(CONCAT('00',h.subdistcode),-2),SUBSTR(CONCAT('00',h.mu),-2)) as areacode
	,@send,DATE_FORMAT(now(),'%Y%m%d%H%i') as d_com,@b_year+543 as b_year
,COUNT(DISTINCT CONCAT(t.hospcode,'-',t.cid)) b

,COUNT(DISTINCT IF(t.f_diag BETWEEN @start_d AND @end_d ,CONCAT(t.hospcode,'-',t.cid),NULL)) b1
,COUNT(DISTINCT IF(t.f_diag < @start_d ,CONCAT(t.hospcode,'-',t.cid),NULL)) b2

,COUNT(DISTINCT IF(t.f_diag BETWEEN @start_d AND @end_d AND t.d365=1 AND t.count_fu>=4,CONCAT(t.hospcode,'-',t.cid),NULL)) a1

,COUNT(DISTINCT IF(t.f_diag < @start_d AND  t.count_fu>=2,CONCAT(t.hospcode,'-',t.cid),NULL)) a2

FROM tmp_smiv_fu t INNER JOIN chospital h on t.HOSPCODE=h.hoscode
INNER JOIN t_person_db p ON t.hospcode=p.hospcode AND t.cid=p.cid
WHERE h.provcode=@prov_c 
AND t.in_year =1 AND p.DISCHARGE IN(9) AND p.NATION IN(99)
GROUP BY h.HOSCODE;
